#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_gelu.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
constexpr int64_t BUFFER_COEFFICIENT = 24;  // From design.md UB allocation table

at::Tensor gelu(const at::Tensor &x, const std::string &approximate)
{
    TORCH_CHECK(x.device().is_privateuseone(), "gelu: x must be on NPU");
    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kBFloat16,
                "gelu: only float16, bfloat16, float32 are supported, got ", x.scalar_type());
    TORCH_CHECK(approximate == "none" || approximate == "tanh",
                "gelu: approximate must be 'none' or 'tanh', got ", approximate);
    TORCH_CHECK(x.is_contiguous(), "gelu: x must be contiguous");

    at::Tensor output = at::empty_like(x);

    int64_t totalLength = x.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = x.element_size();
    int64_t isBf16 = (x.scalar_type() == at::kBFloat16) ? 1 : 0;
    int64_t approximateFlag = (approximate == "tanh") ? 1 : 0;

    // Get hardware parameters
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // Block-level tiling (inter-core split, Cache Line aligned)
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // UB-level tiling (intra-core split)
    int64_t maxTileElements = ubSizeLimit / BUFFER_COEFFICIENT;
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // All arguments must be lvalues
    int64_t formerNumLocal = formerNum;
    int64_t formerLengthLocal = formerLength;
    int64_t tailLengthLocal = tailLength;
    int64_t tileLengthLocal = tileLength;
    int64_t dtypeSizeLocal = dtypeSize;
    int64_t isBf16Local = isBf16;
    int64_t approximateFlagLocal = approximateFlag;

    EXEC_KERNEL_CMD(gelu, blockDim,
                    x, output,
                    formerNumLocal, formerLengthLocal, tailLengthLocal,
                    tileLengthLocal, dtypeSizeLocal, isBf16Local, approximateFlagLocal);

    return output;
}

}  // namespace ascend_kernel
