#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// Approximate tanh(x) using tanh(x) = (exp(2x) - 1) / (exp(2x) + 1)
// Parameters: dst, src are float tensors, tmp1/2 are float scratch buffers.
// dst must not alias with src.
template <bool DUMMY = true>
__aicore__ inline void VecTanh(
    AscendC::LocalTensor<float> dst,
    AscendC::LocalTensor<float> src,
    AscendC::LocalTensor<float> tmp1,
    AscendC::LocalTensor<float> tmp2,
    int64_t count)
{
    // tmp1 = 2 * src
    AscendC::Muls(tmp1, src, 2.0f, count);
    // tmp2 = exp(tmp1)
    AscendC::Exp(tmp2, tmp1, count);
    // tmp1 = exp(2x) - 1
    AscendC::Adds(tmp1, tmp2, -1.0f, count);
    // tmp2 = exp(2x) + 1
    AscendC::Adds(tmp2, tmp2, 1.0f, count);
    // dst = (exp(2x)-1) / (exp(2x)+1)
    AscendC::Div(dst, tmp1, tmp2, count);
}

template <typename T>
class KernelGelu {
public:
    __aicore__ inline KernelGelu() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                int64_t approximate)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;
        this->approximate = approximate;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) == sizeof(float)) {
            pipe.InitBuffer(tempBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tempBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(tempBuf3, tileLength * sizeof(float));
        } else {
            pipe.InitBuffer(castBufX, tileLength * sizeof(float));
            pipe.InitBuffer(castBufY, tileLength * sizeof(float));
            pipe.InitBuffer(tempBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tempBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(tempBuf3, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        if constexpr (sizeof(T) == sizeof(float)) {
            ComputeFP32(curTileLength);
        } else {
            ComputeHalfBF16(curTileLength);
        }
    }

    __aicore__ inline void ComputeFP32(int64_t curTileLength)
    {
        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
        AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
        AscendC::LocalTensor<float> t1 = tempBuf1.Get<float>();
        AscendC::LocalTensor<float> t2 = tempBuf2.Get<float>();
        AscendC::LocalTensor<float> t3 = tempBuf3.Get<float>();

        if (this->approximate == 0) {
            // Exact GELU: x * 0.5 * (1 + erf(x / sqrt(2)))
            // Approximate erf(z) using tanh with: erf(z) ≈ tanh(2z/√π * (1 + 0.044715*z²)
            constexpr float INV_SQRT2 = 0.70710678f;
            constexpr float TWO_OVER_SQRT_PI = 1.12837917f;

            // t1 = x / sqrt(2)
            AscendC::Muls(t1, xLocal, INV_SQRT2, curTileLength);
            // t2 = z * z
            AscendC::Mul(t2, t1, t1, curTileLength);
            // t2 = 1 + 0.044715 * z²
            AscendC::Muls(t3, t2, 0.044715f, curTileLength);
            AscendC::Adds(t2, t3, 1.0f, curTileLength);
            // t3 = z * poly
            AscendC::Mul(t3, t1, t2, curTileLength);
            // t1 = 2/√π * z * poly
            AscendC::Muls(t1, t3, TWO_OVER_SQRT_PI, curTileLength);
            // t2 = tanh(t1) using Exp-based tanh
            AscendC::Muls(t2, t1, 2.0f, curTileLength);
            AscendC::Exp(t3, t2, curTileLength);
            AscendC::Adds(t2, t3, -1.0f, curTileLength);     // exp(2x) - 1
            AscendC::Adds(t3, t3, 1.0f, curTileLength);      // exp(2x) + 1  (t3 = t3 + 1)
            AscendC::Div(t1, t2, t3, curTileLength);         // tanh = (exp-1)/(exp+1)
            // gelu = x * 0.5 * (1 + tanh_result)
            AscendC::Adds(t2, t1, 1.0f, curTileLength);
            AscendC::Muls(t3, t2, 0.5f, curTileLength);
            AscendC::Mul(yLocal, t3, xLocal, curTileLength);
        } else {
            // Tanh GELU: x * 0.5 * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
            constexpr float COEFF_CUBE = 0.044715f;
            constexpr float SQRT_2_OVER_PI = 0.79788456f;

            // t1 = x * x
            AscendC::Mul(t1, xLocal, xLocal, curTileLength);
            // t2 = x^3
            AscendC::Mul(t2, t1, xLocal, curTileLength);
            // t1 = 0.044715 * x^3
            AscendC::Muls(t1, t2, COEFF_CUBE, curTileLength);
            // t2 = x + 0.044715*x^3
            AscendC::Add(t2, t1, xLocal, curTileLength);
            // t1 = sqrt(2/pi) * (x + 0.044715*x^3)
            AscendC::Muls(t1, t2, SQRT_2_OVER_PI, curTileLength);
            // tanh via Exp: tanh(z) = (exp(2z)-1)/(exp(2z)+1)
            AscendC::Muls(t2, t1, 2.0f, curTileLength);     // 2z
            AscendC::Exp(t3, t2, curTileLength);             // exp(2z)
            AscendC::Adds(t2, t3, -1.0f, curTileLength);    // exp(2z)-1
            AscendC::Adds(t3, t3, 1.0f, curTileLength);     // exp(2z)+1
            AscendC::Div(t1, t2, t3, curTileLength);        // tanh
            // gelu = x * 0.5 * (1 + tanh(...))
            AscendC::Adds(t2, t1, 1.0f, curTileLength);
            AscendC::Muls(t3, t2, 0.5f, curTileLength);
            AscendC::Mul(yLocal, t3, xLocal, curTileLength);
        }

        outQueueY.EnQue<float>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void ComputeHalfBF16(int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
        AscendC::LocalTensor<float> xFp32 = castBufX.Get<float>();
        AscendC::LocalTensor<float> yFp32 = castBufY.Get<float>();
        AscendC::LocalTensor<float> t1 = tempBuf1.Get<float>();
        AscendC::LocalTensor<float> t2 = tempBuf2.Get<float>();
        AscendC::LocalTensor<float> t3 = tempBuf3.Get<float>();

        AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

        if (this->approximate == 0) {
            constexpr float INV_SQRT2 = 0.70710678f;
            constexpr float TWO_OVER_SQRT_PI = 1.12837917f;

            AscendC::Muls(t1, xFp32, INV_SQRT2, curTileLength);
            AscendC::Mul(t2, t1, t1, curTileLength);
            AscendC::Muls(t3, t2, 0.044715f, curTileLength);
            AscendC::Adds(t2, t3, 1.0f, curTileLength);
            AscendC::Mul(t3, t1, t2, curTileLength);
            AscendC::Muls(t1, t3, TWO_OVER_SQRT_PI, curTileLength);
            // tanh via Exp
            AscendC::Muls(t2, t1, 2.0f, curTileLength);
            AscendC::Exp(t3, t2, curTileLength);
            AscendC::Adds(t2, t3, -1.0f, curTileLength);
            AscendC::Adds(t3, t3, 1.0f, curTileLength);
            AscendC::Div(t1, t2, t3, curTileLength);
            AscendC::Adds(t2, t1, 1.0f, curTileLength);
            AscendC::Muls(t3, t2, 0.5f, curTileLength);
            AscendC::Mul(yFp32, t3, xFp32, curTileLength);
        } else {
            constexpr float COEFF_CUBE = 0.044715f;
            constexpr float SQRT_2_OVER_PI = 0.79788456f;

            AscendC::Mul(t1, xFp32, xFp32, curTileLength);
            AscendC::Mul(t2, t1, xFp32, curTileLength);
            AscendC::Muls(t1, t2, COEFF_CUBE, curTileLength);
            AscendC::Add(t2, t1, xFp32, curTileLength);
            AscendC::Muls(t1, t2, SQRT_2_OVER_PI, curTileLength);
            // tanh via Exp
            AscendC::Muls(t2, t1, 2.0f, curTileLength);
            AscendC::Exp(t3, t2, curTileLength);
            AscendC::Adds(t2, t3, -1.0f, curTileLength);
            AscendC::Adds(t3, t3, 1.0f, curTileLength);
            AscendC::Div(t1, t2, t3, curTileLength);
            AscendC::Adds(t2, t1, 1.0f, curTileLength);
            AscendC::Muls(t3, t2, 0.5f, curTileLength);
            AscendC::Mul(yFp32, t3, xFp32, curTileLength);
        }

        AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);

        outQueueY.EnQue<T>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castBufY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBuf3;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
    int64_t approximate;
};

extern "C" __global__ __aicore__ void gelu(GM_ADDR x, GM_ADDR y,
                                            int64_t formerNum, int64_t formerLength,
                                            int64_t tailLength, int64_t tileLength,
                                            int64_t dtypeSize, int64_t isBf16,
                                            int64_t approximate)
{
