    } else if (dtypeSize == 2) {
        KernelGelu<half> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, approximate);
        op.Process();
    } else {
        KernelGelu<float> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, approximate);
        op.Process();
    }
}
