#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelGelu {
public:
    __aicore__ inline KernelGelu() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                int64_t approximate)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;
        this->approximate = approximate;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) == sizeof(float)) {
            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
        } else {
            pipe.InitBuffer(upBuf, tileLength * sizeof(float));
            pipe.InitBuffer(downBuf, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        if constexpr (sizeof(T) == sizeof(float)) {
            ComputeFP32(curTileLength);
        } else {
            ComputeHalfBF16(curTileLength);
        }
    }

    // FP32 GELU: uses only Exp/Mul/Add/Adds/Muls/Div
    __aicore__ inline void ComputeFP32(int64_t count)
    {
        AscendC::LocalTensor<float> x = inQueueX.DeQue<float>();
        AscendC::LocalTensor<float> y = outQueueY.AllocTensor<float>();
        AscendC::LocalTensor<float> a = tmpBuf1.Get<float>();
        AscendC::LocalTensor<float> b = tmpBuf2.Get<float>();
        AscendC::LocalTensor<float> c = tmpBuf3.Get<float>();
        AscendC::LocalTensor<float> d = tmpBuf4.Get<float>();

        if (this->approximate == 0) {
            // Exact GELU: x * 0.5 * (1 + erf(x/sqrt(2)))
            // erf(z) ≈ tanh(2z/√pi * (1 + 0.044715*z²))
            // GELU(x) = x * 0.5 * (1 + tanh(2x/(√2·√pi) * (1 + 0.044715*x²/2)))
            //          = x * 0.5 * (1 + tanh(√(2/π)*x * (1 + 0.044715*x²/2)))
            // use sigmoid: GELU(x) = x * sigmoid(1.59576912*x * (1 + 0.044715*x²))
            // 1.59576912 ≈ 2*0.79788456
            // but let's just use the tanh→Exp approach properly
            constexpr float SQRT_2_OVER_PI = 0.79788456f;
            constexpr float C_E = 0.044715f;

            // a = x²
            AscendC::Mul(a, x, x, count);
            // b = 0.044715 * x²
            AscendC::Muls(b, a, C_E, count);
            // c = 1 + 0.044715*x²
            AscendC::Adds(c, b, 1.0f, count);
            // a = x * (1 + 0.044715*x²)
            AscendC::Mul(a, x, c, count);
            // b = √(2/π) * x * (1 + 0.044715*x²)
            AscendC::Muls(b, a, SQRT_2_OVER_PI, count);
            // tanh(b) = (exp(2b)-1)/(exp(2b)+1)
            // c = 2b
            AscendC::Muls(c, b, 2.0f, count);
            // d = exp(2b)
            AscendC::Exp(d, c, count);
            // a = exp(2b) - 1
            AscendC::Adds(a, d, -1.0f, count);
            // b = exp(2b) + 1
            AscendC::Adds(b, d, 1.0f, count);
            // c = tanh(b) = a/b
            AscendC::Div(c, a, b, count);
            // a = 1 + tanh(b)
            AscendC::Adds(a, c, 1.0f, count);
            // b = 0.5 * (1 + tanh(b))
            AscendC::Muls(b, a, 0.5f, count);
            // y = x * 0.5 * (1 + tanh(b))
            AscendC::Mul(y, b, x, count);
        } else {
            // Tanh GELU: x * 0.5 * (1 + tanh(√(2/π)*(x + 0.044715*x³)))
            constexpr float SQRT_2_OVER_PI = 0.79788456f;
            constexpr float C_CUBE = 0.044715f;

            // a = x²
            AscendC::Mul(a, x, x, count);
            // b = x³
            AscendC::Mul(b, a, x, count);
            // a = 0.044715 * x³
            AscendC::Muls(a, b, C_CUBE, count);
            // b = x + 0.044715*x³
            AscendC::Add(b, a, x, count);
            // a = √(2/π) * (x + 0.044715*x³)
            AscendC::Muls(a, b, SQRT_2_OVER_PI, count);
            // tanh via Exp: tanh(z) = (exp(2z)-1)/(exp(2z)+1)
            // b = 2z
            AscendC::Muls(b, a, 2.0f, count);
            // c = exp(2z)
            AscendC::Exp(c, b, count);
            // b = exp(2z) - 1
            AscendC::Adds(b, c, -1.0f, count);
            // d = exp(2z) + 1
            AscendC::Adds(d, c, 1.0f, count);
            // a = tanh(z) = b/d
            AscendC::Div(a, b, d, count);
            // b = 1 + tanh(z)
            AscendC::Adds(b, a, 1.0f, count);
            // c = 0.5 * (1 + tanh(z))
            AscendC::Muls(c, b, 0.5f, count);
            // y = x * c
            AscendC::Mul(y, c, x, count);
        }

        outQueueY.EnQue<float>(y);
        inQueueX.FreeTensor(x);
    }

    // FP16/BF16: Cast → FP32 compute → Cast back
    __aicore__ inline void ComputeHalfBF16(int64_t count)
    {
        AscendC::LocalTensor<T> xh = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yh = outQueueY.AllocTensor<T>();
        AscendC::LocalTensor<float> x = upBuf.Get<float>();
        AscendC::LocalTensor<float> yf = downBuf.Get<float>();
        AscendC::LocalTensor<float> a = tmpBuf1.Get<float>();
        AscendC::LocalTensor<float> b = tmpBuf2.Get<float>();
        AscendC::LocalTensor<float> c = tmpBuf3.Get<float>();
        AscendC::LocalTensor<float> d = tmpBuf4.Get<float>();

        AscendC::Cast(x, xh, AscendC::RoundMode::CAST_NONE, count);

        if (this->approximate == 0) {
            constexpr float SQRT_2_OVER_PI = 0.79788456f;
            constexpr float C_E = 0.044715f;

            AscendC::Mul(a, x, x, count);
            AscendC::Muls(b, a, C_E, count);
            AscendC::Adds(c, b, 1.0f, count);
            AscendC::Mul(a, x, c, count);
            AscendC::Muls(b, a, SQRT_2_OVER_PI, count);
            AscendC::Muls(c, b, 2.0f, count);
            AscendC::Exp(d, c, count);
            AscendC::Adds(a, d, -1.0f, count);
            AscendC::Adds(b, d, 1.0f, count);
            AscendC::Div(c, a, b, count);
            AscendC::Adds(a, c, 1.0f, count);
            AscendC::Muls(b, a, 0.5f, count);
            AscendC::Mul(yf, b, x, count);
        } else {
            constexpr float SQRT_2_OVER_PI = 0.79788456f;
            constexpr float C_CUBE = 0.044715f;

            AscendC::Mul(a, x, x, count);
            AscendC::Mul(b, a, x, count);
            AscendC::Muls(a, b, C_CUBE, count);
